33	/// Mock UI implementation for testing.
34	///
35	/// Captures all UI interactions and allows pre-configured prompt responses.
36	/// Supports both single responses (via `set_prompt_response`) and queued
37	/// responses (via `queue_prompt_responses`) for keys called multiple times.
38	#[derive(Debug, Default)]
39	pub struct MockUI {
40	    mode: OutputMode,
41	    interactive: bool,
42	    messages: Vec<String>,
43	    successes: Vec<String>,
44	    warnings: Vec<String>,
45	    errors: Vec<String>,
46	    headers: Vec<String>,
47	    hints: Vec<String>,
48	    progress: Vec<(usize, usize)>,
49	    spinners: Vec<String>,
50	    error_blocks: Vec<(String, String, Option<String>, usize)>,
51	    prompt_responses: HashMap<String, String>,
52	    prompt_queues: HashMap<String, VecDeque<String>>,
53	    prompts_shown: Vec<String>,
54	    /// Fallback response for any prompt key not in `prompt_responses` or `prompt_queues`.
55	    default_prompt_response: Option<String>,
56	}
57	
58	impl MockUI {
59	    /// Create a new MockUI with Normal output mode.
60	    pub fn new() -> Self {
61	        Self {
62	            mode: OutputMode::Normal,
63	            ..Default::default()
64	        }
65	    }
66	
67	    /// Create a new MockUI with a specific output mode.
68	    pub fn with_mode(mode: OutputMode) -> Self {
69	        Self {
70	            mode,
71	            ..Default::default()
72	        }
73	    }
74	
75	    /// Set a response for a prompt key.
76	    ///
77	    /// When `prompt()` is called with this key, it returns the configured response.
78	    pub fn set_prompt_response(&mut self, key: &str, response: &str) {
79	        self.prompt_responses
80	            .insert(key.to_string(), response.to_string());
81	    }
82	
83	    /// Set multiple prompt responses at once.
84	    pub fn with_prompt_responses(mut self, responses: HashMap<String, String>) -> Self {
85	        self.prompt_responses = responses;
86	        self
87	    }
88	
89	    /// Queue multiple responses for the same prompt key.
90	    ///
91	    /// Responses are returned in order. After the queue is exhausted,
92	    /// falls back to `set_prompt_response` or defaults.
93	    pub fn queue_prompt_responses(&mut self, key: &str, responses: Vec<&str>) {
94	        let queue = responses.into_iter().map(|s| s.to_string()).collect();
95	        self.prompt_queues.insert(key.to_string(), queue);
96	    }
