1040	
1041	        let messages = ui.messages();
1042	        let idx = messages
1043	            .iter()
1044	            .position(|m| m.contains("Running in dry-run mode"))
1045	            .expect("dry-run message should be emitted");
1046	
1047	        assert!(idx > 0, "dry-run message must be preceded by a blank line");
1048	        assert!(
