1	//! Command dispatching.
2	//!
3	//! This module provides the core command infrastructure:
4	//! - [`Command`] trait for implementing commands
5	//! - [`CommandResult`] for uniform result reporting
6	//! - [`CommandDispatcher`] for routing CLI subcommands
7	
8	use std::path::{Path, PathBuf};
9	
10	use crate::cli::args::{Cli, Commands};
11	use crate::config::TrustPolicy;
12	use crate::error::Result;
13	use crate::ui::UserInterface;
14	
15	/// Trait for command implementations.
16	///
17	/// Each CLI subcommand implements this trait to provide its execution logic.
18	pub trait Command {
19	    /// Execute the command.
20	    ///
21	    /// # Arguments
22	    ///
23	    /// * `ui` - User interface for displaying output and prompts
24	    ///
25	    /// # Returns
26	    ///
27	    /// A [`CommandResult`] indicating success/failure and exit code.
28	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult>;
29	}
30	
31	/// Result of command execution.
32	#[derive(Debug)]
33	pub struct CommandResult {
34	    /// Whether the command succeeded.
35	    pub success: bool,
36	
37	    /// Exit code to use (0 for success, non-zero for failure).
38	    pub exit_code: i32,
39	}
40	
41	impl CommandResult {
42	    /// Create a successful result.
43	    pub fn success() -> Self {
44	        Self {
45	            success: true,
46	            exit_code: 0,
47	        }
48	    }
49	
50	    /// Create a failure result.
51	    pub fn failure(exit_code: i32) -> Self {
52	        Self {
53	            success: false,
54	            exit_code,
55	        }
56	    }
57	}
58	
59	/// Dispatches CLI commands to their implementations.
60	pub struct CommandDispatcher {
61	    project_root: PathBuf,
62	    config_override: Option<PathBuf>,
63	}
64	
65	impl CommandDispatcher {
66	    /// Create a new dispatcher for the given project root.
67	    pub fn new(project_root: PathBuf) -> Self {
68	        Self {
69	            project_root,
70	            config_override: None,
71	        }
72	    }
73	
74	    /// Set an override config path (from `--config` flag).
75	    pub fn with_config_override(mut self, config_override: Option<PathBuf>) -> Self {
76	        self.config_override = config_override;
77	        self
78	    }
79	
80	    /// Get the project root path.
81	    pub fn project_root(&self) -> &Path {
82	        &self.project_root
83	    }
84	
85	    /// Dispatch and execute a command.
86	    ///
87	    /// Routes the CLI subcommand to the appropriate command implementation
88	    /// and executes it.
89	    pub fn dispatch(&self, cli: &Cli, ui: &mut dyn UserInterface) -> Result<CommandResult> {
90	        // Determine trust policy from CLI flags
91	        let trust_policy = if cli.trust {
92	            TrustPolicy::TrustAll
93	        } else if ui.is_interactive() {
94	            TrustPolicy::Prompt
95	        } else {
96	            TrustPolicy::Reject
97	        };
98	
99	        let config_override = self.config_override.clone().or_else(|| cli.config.clone());
100	
101	        match &cli.command {
102	            Some(Commands::Run(args)) => {
103	                let cmd = super::run::RunCommand::new(&self.project_root, args.clone())
104	                    .with_trust_policy(trust_policy)
105	                    .with_config_override(config_override);
106	                cmd.execute(ui)
107	            }
108	            Some(Commands::Init(args)) => {
109	                let cmd = super::init::InitCommand::new(&self.project_root, args.clone());
110	                cmd.execute(ui)
111	            }
112	            Some(Commands::Add(args)) => {
113	                let cmd = super::add::AddCommand::new(&self.project_root, args.clone())
114	                    .with_config_override(config_override);
115	                cmd.execute(ui)
116	            }
117	            Some(Commands::Templates(args)) => {
118	                let cmd = super::templates::TemplatesCommand::new(&self.project_root, args.clone());
119	                cmd.execute(ui)
120	            }
121	            Some(Commands::Status(args)) => {
122	                let cmd = super::status::StatusCommand::new(&self.project_root, args.clone())
123	                    .with_config_override(config_override);
124	                cmd.execute(ui)
125	            }
126	            Some(Commands::List(args)) => {
127	                let cmd = super::list::ListCommand::new(&self.project_root, args.clone())
128	                    .with_config_override(config_override);
129	                cmd.execute(ui)
130	            }
131	            Some(Commands::Last(args)) => {
132	                let cmd = super::last::LastCommand::new(&self.project_root, args.clone());
133	                cmd.execute(ui)
134	            }
135	            Some(Commands::History(args)) => {
136	                let cmd = super::history::HistoryCommand::new(&self.project_root, args.clone());
137	                cmd.execute(ui)
138	            }
139	            Some(Commands::Lint(args)) => {
140	                let cmd = super::lint::LintCommand::new(&self.project_root, args.clone())
141	                    .with_config_override(config_override);
142	                cmd.execute(ui)
143	            }
144	            Some(Commands::Config(args)) => {
145	                let cmd = super::config::ConfigCommand::new(&self.project_root, args.clone())
146	                    .with_config_override(config_override);
147	                cmd.execute(ui)
148	            }
149	            Some(Commands::Cache(args)) => {
150	                let cmd = super::cache::CacheCommand::new(args.clone());
151	                cmd.execute(ui)
152	            }
153	            Some(Commands::Feedback(args)) => {
154	                let cmd = super::feedback::FeedbackCommand::new(args.clone());
155	                cmd.execute(ui)
156	            }
157	            Some(Commands::Update(args)) => {
158	                let cmd = super::update::UpdateCommand::new(args.clone());
159	                cmd.execute(ui)
160	            }
161	            Some(Commands::Snapshot(args)) => {
162	                let cmd = super::snapshot::SnapshotCommand::new(&self.project_root, args.clone())
163	                    .with_config_override(config_override);
164	                cmd.execute(ui)
165	            }
166	            Some(Commands::Completions(args)) => {
167	                let cmd = super::completions::CompletionsCommand::new(args.clone());
168	                cmd.execute(ui)
169	            }
170	            Some(Commands::Schema(args)) => {
171	                let cmd = super::schema::SchemaCommand::new(args.clone());
172	                cmd.execute(ui)
173	            }
174	            None => {
175	                // Default to run command with default args
176	                let cmd = super::run::RunCommand::new(
177	                    &self.project_root,
178	                    crate::cli::args::RunArgs::default(),
179	                )
180	                .with_trust_policy(trust_policy)
181	                .with_config_override(config_override);
182	                cmd.execute(ui)
183	            }
184	        }
185	    }
186	}
