41	/// Orchestrates the execution of a workflow.
42	pub struct WorkflowRunner<'a> {
43	    pub(super) config: &'a BivvyConfig,
44	    pub(super) steps: HashMap<String, ResolvedStep>,
45	    pub(super) snapshot_store: SnapshotStore,
46	}
47	
48	/// Result of running a workflow.
49	#[derive(Debug)]
50	pub struct WorkflowResult {
51	    /// Workflow name.
52	    pub workflow: String,
53	    /// Results from each executed step.
54	    pub steps: Vec<StepResult>,
55	    /// Names of skipped steps.
56	    pub skipped: Vec<String>,
57	    /// Total duration.
58	    pub duration: Duration,
59	    /// Whether all steps succeeded.
60	    pub success: bool,
61	    /// Whether the workflow was aborted by the user during recovery.
62	    pub aborted: bool,
63	}
64	
65	/// Options for running a workflow.
66	#[derive(Debug, Default)]
67	pub struct RunOptions {
68	    /// Workflow name (defaults to "default").
69	    pub workflow: Option<String>,
70	    /// Only run these steps.
71	    pub only: HashSet<String>,
72	    /// Skip these steps.
73	    pub skip: HashSet<String>,
74	    /// How to handle skipped step dependencies.
75	    pub skip_behavior: SkipBehavior,
76	    /// Force re-run these steps even if complete.
77	    pub force: HashSet<String>,
78	    /// Force re-run every step in the workflow, bypassing all checks.
79	    pub force_all: bool,
80	    /// Dry run mode.
81	    pub dry_run: bool,
82	    /// Requirements that are provided by the environment and should skip gap checks.
83	    pub provided_requirements: HashSet<String>,
84	    /// Active environment name for only_environments filtering.
85	    pub active_environment: Option<String>,
86	    /// Use the diagnostic funnel pipeline for error recovery.
87	    pub diagnostic_funnel: bool,
88	    /// Discard all persisted satisfaction records and evaluate everything fresh.
89	    pub fresh: bool,
90	}
91	
92	impl RunOptions {
93	    /// Whether the named step should be forced to run, bypassing checks.
94	    ///
95	    /// A step is forced if `force_all` is set, or if its name appears in the
96	    /// `force` set. Step- and workflow-level force directives are merged into
97	    /// these fields by the caller before the runner is invoked.
98	    pub fn should_force(&self, step_name: &str) -> bool {
99	        self.force_all || self.force.contains(step_name)
100	    }
101	}
