103	impl<'a> WorkflowRunner<'a> {
104	    /// Create a new workflow runner with an in-memory snapshot store.
105	    pub fn new(config: &'a BivvyConfig, steps: HashMap<String, ResolvedStep>) -> Self {
106	        Self {
107	            config,
108	            steps,
109	            snapshot_store: SnapshotStore::empty(),
110	        }
111	    }
112	
113	    /// Create a new workflow runner with a specific snapshot store.
114	    pub fn with_snapshot_store(
115	        config: &'a BivvyConfig,
116	        steps: HashMap<String, ResolvedStep>,
117	        snapshot_store: SnapshotStore,
118	    ) -> Self {
119	        Self {
120	            config,
121	            steps,
122	            snapshot_store,
123	        }
124	    }
125	
126	    /// Get a mutable reference to the snapshot store (for saving after run).
127	    pub fn snapshot_store_mut(&mut self) -> &mut SnapshotStore {
128	        &mut self.snapshot_store
129	    }
130	
131	    /// Run the specified workflow.
132	    ///
133	    /// `base_env` is the YAML-derived env stack (settings + workflow), already
134	    /// merged in priority order. `process_env` is the parent process
135	    /// environment, which wins over both `base_env` and any step-level env.
136	    #[allow(clippy::too_many_arguments)]
137	    pub fn run(
138	        &mut self,
139	        options: &RunOptions,
140	        context: &InterpolationContext,
141	        base_env: &HashMap<String, String>,
142	        process_env: &HashMap<String, String>,
143	        project_root: &Path,
144	    ) -> Result<WorkflowResult> {
145	        let mut event_bus = EventBus::new();
146	        self.run_with_progress(
147	            options,
148	            context,
149	            base_env,
150	            process_env,
151	            project_root,
152	            None,
153	            None,
154	            |_| {},
155	            &mut event_bus,
156	        )
157	    }
158	
159	    /// Run the specified workflow with a progress callback.
160	    #[allow(clippy::too_many_arguments)]
161	    pub fn run_with_progress(
162	        &mut self,
163	        options: &RunOptions,
164	        context: &InterpolationContext,
165	        base_env: &HashMap<String, String>,
166	        process_env: &HashMap<String, String>,
167	        project_root: &Path,
168	        mut gap_checker: Option<&mut GapChecker<'_>>,
169	        mut state: Option<&mut StateStore>,
170	        mut on_progress: impl FnMut(RunProgress<'_>),
171	        _event_bus: &mut EventBus,
172	    ) -> Result<WorkflowResult> {
173	        let start = Instant::now();
174	        let workflow_name = options.workflow.as_deref().unwrap_or("default");
175	
176	        // Build dependency graph and execution plan
177	        let graph = self.build_graph(workflow_name)?;
