fn _interact_on(self, term: &Term, allow_quit: bool) -> Result<Option<Vec<usize>>> {
    if !term.is_term() {
        return Err(io::Error::new(io::ErrorKind::NotConnected, "not a terminal").into());
    }

    if self.items.is_empty() {
        return Err(io::Error::new(
            io::ErrorKind::Other,
            "Empty list of items given to `MultiSelect`",
        ))?;
    }

    let mut paging = Paging::new(term, self.items.len(), self.max_length);
    let mut render = TermThemeRenderer::new(term, self.theme);
    let mut sel = 0;

    let mut size_vec = Vec::new();

    for items in self
        .items
        .iter()
        .flat_map(|i| i.split('\n'))
        .collect::<Vec<_>>()
    {
        let size = &items.len();
        size_vec.push(*size);
    }

    let mut checked: Vec<bool> = self.defaults.clone();

    term.hide_cursor()?;

    loop {
        if let Some(ref prompt) = self.prompt {
            paging
                .render_prompt(|paging_info| render.multi_select_prompt(prompt, paging_info))?;
        }

        for (idx, item) in self
            .items
            .iter()
            .enumerate()
            .skip(paging.current_page * paging.capacity)
            .take(paging.capacity)
        {
            render.multi_select_prompt_item(item, checked[idx], sel == idx)?;
        }

        term.flush()?;

        match term.read_key()? {
            Key::ArrowDown | Key::Tab | Key::Char('j') => {
                if sel == !0 {
                    sel = 0;
                } else {
                    sel = (sel as u64 + 1).rem(self.items.len() as u64) as usize;
                }
            }
            Key::ArrowUp | Key::BackTab | Key::Char('k') => {
                if sel == !0 {
                    sel = self.items.len() - 1;
                } else {
                    sel = ((sel as i64 - 1 + self.items.len() as i64)
                        % (self.items.len() as i64)) as usize;
                }
            }
            Key::ArrowLeft | Key::Char('h') => {
                if paging.active {
                    sel = paging.previous_page();
                }
            }
            Key::ArrowRight | Key::Char('l') => {
                if paging.active {
                    sel = paging.next_page();
                }
            }
            Key::Char(' ') => {
                checked[sel] = !checked[sel];
            }
            Key::Char('a') => {
                if checked.iter().all(|&item_checked| item_checked) {
                    checked.fill(false);
                } else {
                    checked.fill(true);
                }
            }
            Key::Escape | Key::Char('q') => {
                if allow_quit {
                    if self.clear {
                        render.clear()?;
                    } else {
                        term.clear_last_lines(paging.capacity)?;
                    }

                    term.show_cursor()?;
                    term.flush()?;

                    return Ok(None);
                }
            }
            Key::Enter => {
                if self.clear {
                    render.clear()?;
                }

                if let Some(ref prompt) = self.prompt {
                    if self.report {
                        let selections: Vec<_> = checked
                            .iter()
                            .enumerate()
                            .filter_map(|(idx, &checked)| {
                                if checked {
                                    Some(self.items[idx].as_str())
                                } else {
                                    None
                                }
